//! Raw bindings of the ProGPU native C ABI (`progpu_native.h`, ABI version 5, with its WebGPU
//! entry `progpu_native_dawn.h`) and of the WebGPU C ABI it runs on (`webgpu.h` of webgpu-headers
//! 673658bc with wgpu-native's `wgpu.h` and the Metal interop of `FerroUI/wgpu-native`
//! branch `progpu/wgpu-30`, on wgpu-core 30), generated by `bindgen` (`regenerate.sh`).
//!
//! Everything is linked statically: the engine (`progpu_native_dawn` and the archives it is made
//! of, built by `build.rs` from the ProGPU sources) and wgpu-native, a Rust dependency. The engine
//! calls WebGPU through the procedures a resolver gives it ([`resolve_webgpu_proc`]: those of the
//! linked wgpu-native), so the same engine runs on Dawn when a host resolves Dawn's procedures and
//! hands it a Dawn device. The linker keeps what the program reaches.
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code, clippy::all)]

// The WebGPU implementation of the engine: linked for its C functions.
extern crate wgpu_native;

/// The ProGPU native C ABI.
pub mod progpu {
    include!("progpu_native.rs");
}

/// The C ABI over the retained scene builder (`native/progpu_native_scene_builder_c.h`), linked
/// statically with the builder.
pub mod scene_builder {
    include!("scene_builder.rs");
}

/// The C ABI over the engine's font stack (`native/progpu_native_font_c.h`): the system font
/// catalog, faces from bytes, tables, metrics and unhinted glyph outlines, linked statically.
pub mod font {
    include!("font.rs");
}

/// The C ABI over the engine's image module (`native/progpu_native_image_c.h`): the size of a PNG
/// and its pixels as RGBA, linked statically.
pub mod image {
    include!("image.rs");
}

/// The wgpu-native WebGPU C ABI, with the native-object interop of the fork.
pub mod webgpu {
    include!("webgpu.rs");
}

/// The version of the ProGPU native SDK these bindings are generated from.
pub const SDK_VERSION: &str = "0.1.0-preview.70";

/// The procedure resolver of `progpu_native_dawn_engine_create` (`resolve_proc`): the WebGPU
/// procedures of the linked wgpu-native, by name (`wgpuGetProcAddress`). The context is unused.
///
/// # Safety
/// `name` is a NUL-terminated string.
pub unsafe extern "C" fn resolve_webgpu_proc(_context: *mut core::ffi::c_void, name: *const core::ffi::c_char) -> *mut core::ffi::c_void {
    if name.is_null() {
        return core::ptr::null_mut();
    }
    // SAFETY: a NUL-terminated string, borrowed for the call.
    let name = unsafe { core::ffi::CStr::from_ptr(name) };
    let view = webgpu::WGPUStringView { data: name.as_ptr(), length: name.to_bytes().len() };
    // SAFETY: a pure lookup of the linked implementation.
    match unsafe { webgpu::wgpuGetProcAddress(view) } {
        Some(procedure) => procedure as *mut core::ffi::c_void,
        None => core::ptr::null_mut(),
    }
}

/// The context of [`resolve_webgpu_proc`] for `progpu_native_dawn_engine_options` (which requires
/// one that is not null): the resolver uses none, so it is the address of this static.
pub fn resolver_context() -> *mut core::ffi::c_void {
    static CONTEXT: u8 = 0;
    &CONTEXT as *const u8 as *mut core::ffi::c_void
}

/// Whether the linked engine has the ABI version of these bindings.
pub fn abi_matches() -> bool {
    // SAFETY: a plain query without arguments.
    unsafe { progpu::progpu_native_get_abi_version() == progpu::PROGPU_NATIVE_ABI_VERSION }
}
